            "{\n.reg .pred p;\n setp.ne.b32 p, %37, 0;\n"
            "wgmma.mma_async.sync.aligned.m64n64k16.f32.f16.f16 " PF_ACC32 ",{%32,%33,%34,%35},%36,p,%38,%39,%40;\n}\n"
            : PF_OUT32(acc, O)
            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
